public void Update()
		{
			stateCnt_ = (stateCnt_ + 1) % int.MaxValue;
			gameStateCnt_ = (gameStateCnt_ + 1) % int.MaxValue;
			frame_ = (frame_ + 1) % int.MaxValue;
