			{
				if (stateCnt_ == WAIT_THROWIN[0])
				{
					SetBallTeam(1 - udat_.ball_.lastOwner_.team_id_);
					udat_.teams_[0].SetPositionThrowIn();
					udat_.teams_[1].SetPositionThrowIn();
				}
			}
			else if (state_ == 4)
			{
				if (stateCnt_ == WAIT_GK[0])
