public void Update()
		{
			stateCnt_ = (stateCnt_ + 1) % int.MaxValue;
			if (state_ == 3)
			{
				if (stateCnt_ >= 12)
				{
					ChangeState(0);
					apdat_.mapMain_.UpdateTenantMapcip();
				}
				return;
			}
			TenantData tenantData = null;
			if (tenantDataId_ == -1)
			{
